<?php defined('BASEPATH') OR exit('No direct script access allowed'); function spmi_report_print_value($value) { $value = trim((string) $value); return $value === '' ? '-' : $value; } function spmi_report_print_auditor_evidence($value) { $items = json_decode((string) $value, TRUE); if (!is_array($items)) return [(string) $value]; $lines = []; foreach ($items as $item) { if (!is_array($item)) continue; $lines[] = (string) (isset($item['original_name']) ? $item['original_name'] : '-') . ' / ' . (string) (isset($item['mime_type']) ? $item['mime_type'] : '-') . ' / ' . (string) (isset($item['size_bytes']) ? (int) $item['size_bytes'] : 0) . ' bytes / ' . (string) (isset($item['sha256']) ? $item['sha256'] : '-'); } return $lines ?: ['-']; } ?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?php echo html_escape($title); ?></title><style>body{font-family:Arial,sans-serif;color:#222;margin:24px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #999;padding:6px;vertical-align:top}th{background:#eee}.toolbar{margin-bottom:20px}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><strong>Gunakan dialog browser: pilih “Save as PDF”.</strong> <button type="button" onclick="window.print()">Print / Save as PDF</button></div><h1><?php echo html_escape($report->report_number); ?></h1><p><?php echo html_escape($report->cycle_code_snapshot . ' — ' . $report->cycle_title_snapshot); ?><br><?php echo html_escape($report->auditee_name_snapshot); ?> | <?php echo html_escape($report->assessment_finalized_at_snapshot); ?></p><table><thead><tr><th>No</th><th>Pertanyaan</th><th>Realisasi & Bukti</th><th>Skor</th><th>Deskriptor</th><th>Temuan</th><th>Rekomendasi</th><th>Rencana perbaikan</th><th>Tanggal bukti</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php echo html_escape($item->display_order); ?></td><td><?php echo html_escape($item->question_code_snapshot); ?><br><?php echo nl2br(html_escape($item->question_text_snapshot)); ?></td><td><?php echo nl2br(html_escape($item->realization_snapshot)); ?><br>URL: <?php echo nl2br(html_escape(spmi_report_print_value(isset($item->evidence_url_snapshot) ? $item->evidence_url_snapshot : NULL))); ?><br>File: <?php echo nl2br(html_escape(spmi_report_print_value(isset($item->evidence_file_original_name_snapshot) ? $item->evidence_file_original_name_snapshot : NULL))); ?><br>MIME: <?php echo nl2br(html_escape(spmi_report_print_value(isset($item->evidence_file_mime_type_snapshot) ? $item->evidence_file_mime_type_snapshot : NULL))); ?><br>Ukuran: <?php echo nl2br(html_escape(spmi_report_print_value(isset($item->evidence_file_size_bytes_snapshot) ? $item->evidence_file_size_bytes_snapshot : NULL))); ?><br>SHA-256: <?php echo nl2br(html_escape(spmi_report_print_value(isset($item->evidence_file_sha256_snapshot) ? $item->evidence_file_sha256_snapshot : NULL))); ?><br><?php foreach (spmi_report_print_auditor_evidence(isset($item->auditor_evidence_snapshot) ? $item->auditor_evidence_snapshot : NULL) as $line): ?><?php echo nl2br(html_escape($line)); ?><br><?php endforeach; ?></td><td><?php echo html_escape($item->score); ?></td><td><?php echo nl2br(html_escape($item->descriptor_snapshot)); ?></td><td><?php echo html_escape(spmi_report_print_value(isset($item->finding_type_snapshot) ? $item->finding_type_snapshot : NULL)); ?><br><?php echo nl2br(html_escape(spmi_report_print_value(isset($item->finding_snapshot) ? $item->finding_snapshot : NULL))); ?></td><td><?php echo nl2br(html_escape(spmi_report_print_value(isset($item->recommendation_snapshot) ? $item->recommendation_snapshot : NULL))); ?></td><td><?php echo nl2br(html_escape(spmi_report_print_value(isset($item->improvement_plan_snapshot) ? $item->improvement_plan_snapshot : NULL))); ?></td><td><?php echo html_escape(spmi_report_print_value(isset($item->evidence_date_snapshot) ? $item->evidence_date_snapshot : NULL)); ?></td></tr><?php endforeach; ?></tbody></table></body></html>
